// Generates passkey fixtures with @simplewebauthn/server (the library behind
// @better-auth/passkey) so the Go plugin can be checked against it:
//   - registration options generated by simplewebauthn (shape and key order),
//   - registration responses ("none" and "packed" self attestation) with the passkey row
//     the TypeScript plugin stores for them (publicKey = base64 of the COSE key),
//   - an authentication response that simplewebauthn verifies against that row.
// Output: plugins/passkey/testdata/fixtures.json
import { writeFileSync, mkdirSync } from "node:fs";
import {
  generateRegistrationOptions,
  generateAuthenticationOptions,
  verifyRegistrationResponse,
  verifyAuthenticationResponse,
} from "@simplewebauthn/server";
import { base64 } from "@better-auth/utils/base64";
import { SoftAuthenticator } from "../lib/passkey-authenticator.mjs";

const origin = "http://localhost:3000";
const rpID = "localhost";
const out = { origin, rpID, options: null, cases: [] };

out.options = await generateRegistrationOptions({
  rpName: "Better Auth",
  rpID,
  userID: new TextEncoder().encode("abcdefghijklmnopqrstuvwxyz012345"),
  userName: "test@test.com",
  userDisplayName: "test@test.com",
  attestationType: "none",
  challenge: new Uint8Array(32).fill(7),
  excludeCredentials: [
    { id: "Y3JlZC0x", transports: ["internal", "hybrid"] },
    { id: "Y3JlZC0y==", transports: [""] },
    { id: "Y3JlZC0z", transports: undefined },
  ],
  authenticatorSelection: { residentKey: "preferred", userVerification: "preferred", authenticatorAttachment: "platform" },
  extensions: { credProps: false, minPinLength: true },
});

for (const attestation of ["none", "packed"]) {
  const authr = new SoftAuthenticator({ origin, attestation });
  const regOptions = await generateRegistrationOptions({ rpName: "Better Auth", rpID, userName: "u", attestationType: "none" });
  const registration = authr.register(regOptions);
  const verified = await verifyRegistrationResponse({
    response: registration, expectedChallenge: regOptions.challenge, expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: false,
  });
  if (!verified.verified) throw new Error("registration not verified");
  const info = verified.registrationInfo;
  // The row routes.ts persists.
  const row = {
    credentialID: info.credential.id,
    publicKey: base64.encode(info.credential.publicKey),
    counter: info.credential.counter,
    deviceType: info.credentialDeviceType,
    transports: registration.response.transports?.join(",") ?? "",
    backedUp: info.credentialBackedUp,
    aaguid: info.aaguid,
  };
  const authOptions = await generateAuthenticationOptions({ rpID, userVerification: "preferred" });
  const authentication = authr.authenticate(authOptions);
  const auth = await verifyAuthenticationResponse({
    response: authentication, expectedChallenge: authOptions.challenge, expectedOrigin: origin, expectedRPID: rpID,
    credential: { id: row.credentialID, publicKey: base64.decode(row.publicKey), counter: row.counter }, requireUserVerification: false,
  });
  if (!auth.verified) throw new Error("authentication not verified");
  out.cases.push({
    attestation,
    registration: { challenge: regOptions.challenge, response: registration },
    row,
    authentication: { challenge: authOptions.challenge, response: authentication, newCounter: auth.authenticationInfo.newCounter },
  });
}

const dir = new URL("../../plugins/passkey/testdata/", import.meta.url);
mkdirSync(dir, { recursive: true });
writeFileSync(new URL("fixtures.json", dir), JSON.stringify(out, null, 2) + "\n");
console.log("wrote plugins/passkey/testdata/fixtures.json");
